// Wi-Fi lab W2: phone control.
//   uv run pio run -d labs/wifi-lab-w2 -e wifi-lab-w2 -t upload          variation 1: control on your Wi-Fi
//   uv run pio run -d labs/wifi-lab-w2 -e wifi-lab-w2-remote -t upload   variation 2: also from anywhere, through your
//                                                    dashboard server and a tunnel (remote.h)
// Everything from W1 (scanner views, join, status) plus a web server: REST API + WebSocket,
// a phone page at http://bench.local, a set-up network for joining without a cable, firmware
// updates over HTTP, and the desktop dashboard in esp32-labs/apps/dashboard.
//
// Wiring: the screen from lesson 03. The push button on GPIO 5 is optional: it does exactly what
// BOOT does, and with nothing wired its internal pull-up keeps it quiet.
//
// Views: networks · channels · radar · status · message
// Button or BOOT: click = next view · double-click = scan now · long press = auto-scan on/off
// Serial: scan | view <1-5> | auto on|off | join <n> | forget | reconnect | status | tz <TZ> |
//         ping [ip] | setup | token | token new | relay [url|off] | help
//
// Web: http://bench.local (phone page), /api (REST), /ws (live). See web_api.h.
// The saved network is shared with W1 (same NVS namespace), so switching labs keeps it.
#include <Arduino.h>
#include <ArduinoJson.h>
#include <WiFi.h>
#include <esp_heap_caps.h>

#include "api_rules.h"
#include "api_token.h"
#include "button.h"
#include "color.h"
#include "commands.h"
#include "connection.h"
#include "display.h"
#include "pinger.h"
#include "pins.h"
#include "remote.h"
#include "scanner.h"
#include "setup_portal.h"
#include "views.h"
#include "web_api.h"
#include "web_views.h"

namespace {

constexpr uint32_t kAutoScanMs = 10'000;        // pause between automatic scans when not joined
// When joined, every scan takes the radio off the router's channel for ~3 s, and web requests
// arriving meanwhile get lost. So scan much less often once we're on a network.
constexpr uint32_t kAutoScanJoinedMs = 60'000;
constexpr uint32_t kPageFlipMs = 4'000;    // list view: next page after this long
constexpr uint32_t kStatusPushMs = 1'000;  // live status to web clients
constexpr uint32_t kPortalAfterFailMs = 60'000;
constexpr uint32_t kPortalCloseAfterJoinMs = 30'000;
constexpr int kStatusView = 3, kMessageView = 4;
const char *const kViewNames[] = {"networks", "channels", "radar", "status", "message"};
constexpr int kViews = sizeof(kViewNames) / sizeof(kViewNames[0]);
constexpr const char *kFirmware = "wifi-lab-w2";

Display display;
Scanner scanner;
Connection connection;
SetupPortal portal;
ApiToken token;
Pinger pinger;
CommandQueue commands;
ApiRules rules(commands, connection, kViewNames, kViews);
WebApi web(rules, commands, token);
Button external(PIN_BUTTON, "button");
Button boot(PIN_BOOT_BTN, "BOOT");

struct {
  int view = 0;
  int page = 0;
  bool autoScan = true;
  uint8_t backlight = 255;
  uint8_t r = 0, g = 0, b = 0;  // on-board RGB LED
  String message;
  uint32_t pageFlippedAt = 0;
  String pendingSsid;  // set by `join <n>`: the next serial line is the password
  bool awaitingPassword = false;
  uint32_t rebootAt = 0;  // set by a reboot command; 0 = none
  float tempC = NAN;
} state;

// ---- JSON snapshots for the web --------------------------------------------------------

const char *wifiStateName(Connection::State s) {
  switch (s) {
    case Connection::State::Connected: return "connected";
    case Connection::State::Connecting: return "connecting";
    case Connection::State::Failed: return "failed";
    default: return "not-set-up";
  }
}

String statusJson() {
  JsonDocument doc;
  doc["firmware"] = kFirmware;
  doc["uptimeS"] = millis() / 1000;
  doc["heapFree"] = ESP.getFreeHeap();
  doc["psramFree"] = ESP.getFreePsram();
  if (!isnan(state.tempC)) doc["tempC"] = serialized(String(state.tempC, 1));
  doc["clients"] = web.clients();

  JsonObject wifi = doc["wifi"].to<JsonObject>();
  wifi["state"] = wifiStateName(connection.state());
  wifi["ssid"] = connection.ssid();
  wifi["hostname"] = String(Connection::kHostname) + ".local";
  if (connection.state() == Connection::State::Connected) {
    wifi["ip"] = WiFi.localIP().toString();
    wifi["rssi"] = WiFi.RSSI();
    wifi["channel"] = WiFi.channel();
  }
  wifi["reason"] = Connection::reasonHint(connection.lastReason());

  JsonObject link = doc["remote"].to<JsonObject>();
  link["state"] = remote::stateName(remote::state());

  JsonObject setup = doc["setup"].to<JsonObject>();
  setup["active"] = portal.active();
  setup["ssid"] = SetupPortal::kSsid;  // the password is only on the screen, never in the API

  JsonObject screen = doc["screen"].to<JsonObject>();
  screen["view"] = kViewNames[state.view];
  JsonArray names = screen["views"].to<JsonArray>();
  for (const char *n : kViewNames) names.add(n);
  screen["autoScan"] = state.autoScan;
  screen["backlight"] = state.backlight;
  screen["message"] = state.message;

  JsonObject led = doc["led"].to<JsonObject>();
  led["r"] = state.r, led["g"] = state.g, led["b"] = state.b;

  JsonObject scan = doc["scan"].to<JsonObject>();
  scan["running"] = scanner.scanning();
  scan["count"] = scanner.networks().size();
  scan["durationMs"] = scanner.lastScanMs();

  String out;
  serializeJson(doc, out);
  return out;
}

String networksJson() {
  JsonDocument doc;
  doc["scans"] = scanner.scans();
  doc["durationMs"] = scanner.lastScanMs();
  JsonArray list = doc["networks"].to<JsonArray>();
  for (const ScanResult &n : scanner.networks()) {
    JsonObject o = list.add<JsonObject>();
    o["ssid"] = n.ssid;  // hardware addresses (BSSIDs) stay off the web on purpose
    o["rssi"] = n.rssi;
    o["channel"] = n.channel;
    o["auth"] = authName(n.auth);
  }
  String out;
  serializeJson(doc, out);
  return out;
}

void pushEvent(const char *source, const char *gesture) {
  JsonDocument doc;
  doc["source"] = source;
  doc["gesture"] = gesture;
  doc["uptimeS"] = millis() / 1000;
  String out;
  serializeJson(doc, out);
  web.publishEvent(out);
  remote::publish("event", out);
}

// ---- Serial output ---------------------------------------------------------------------

void printResults() {
  const auto &nets = scanner.networks();
  Serial.printf("\n--- scan %lu: %u networks in %lu ms ---\n", static_cast<unsigned long>(scanner.scans()),
                unsigned(nets.size()), static_cast<unsigned long>(scanner.lastScanMs()));
  Serial.println(" #   dBm  ch  security    bssid              ssid");
  for (size_t i = 0; i < nets.size(); i++) {
    const ScanResult &n = nets[i];
    Serial.printf("%2u  %4ld  %2u  %-10s  %s  %s\n", unsigned(i + 1), static_cast<long>(n.rssi), n.channel,
                  authName(n.auth), n.bssid.c_str(), n.ssid.isEmpty() ? "(hidden)" : n.ssid.c_str());
  }
  Serial.println("To join one: join <#>");
}

void printRelay() {
  const String url = remote::url();
  Serial.printf("Remote link: %s%s%s\n", remote::stateName(remote::state()), url.isEmpty() ? "" : " | ", url.c_str());
}

void printStatus() {
  using State = Connection::State;
  switch (connection.state()) {
    case State::NoCredentials: Serial.println("Not joined. Scan, then: join <#>"); break;
    case State::Connecting: Serial.printf("Joining '%s'...\n", connection.ssid().c_str()); break;
    case State::Failed: Serial.printf("Could not join '%s': %s\n", connection.ssid().c_str(), Connection::reasonHint(connection.lastReason())); break;
    case State::Connected:
      Serial.printf("Joined '%s' | IP %s | http://%s.local | ch %d | %ld dBm | time %s | web clients %u\n",
                    connection.ssid().c_str(), WiFi.localIP().toString().c_str(), Connection::kHostname,
                    static_cast<int>(WiFi.channel()), static_cast<long>(WiFi.RSSI()),
                    connection.timeSynced() ? "synced" : "not yet", unsigned(web.clients()));
      break;
  }
  if (portal.active()) Serial.printf("Set-up network '%s' is open (password on the screen)\n", SetupPortal::kSsid);
  if (remote::builtIn()) printRelay();
}

void printHelp() {
  Serial.println();
  Serial.println("Commands: scan | view <1-5> | auto on|off | join <#> | forget | reconnect | status | tz <TZ>");
  Serial.println("          ping (the router) | ping <ip> (e.g. your computer: can the board reach it?)");
  Serial.println("          setup (open the set-up network) | token (show admin token) | token new | help");
  if (remote::builtIn()) Serial.println("          relay (show) | relay wss://<tunnel host> (save + connect) | relay off");
  Serial.println("Button (GPIO 5) or BOOT: click = next view, double-click = scan now, long press = auto-scan on/off");
}

// ---- Actions (shared by the button, serial and web) -------------------------------------

uint32_t autoScanInterval() {
  return connection.state() == Connection::State::Connected ? kAutoScanJoinedMs : kAutoScanMs;
}

void scanNow(const char *why) {
  if (scanner.start()) log_i("scan started (%s)", why);
}

void setView(int v) {
  state.view = (v % kViews + kViews) % kViews;
  state.page = 0;
  state.pageFlippedAt = millis();
  log_i("view %d: %s", state.view + 1, kViewNames[state.view]);
}

void setAuto(bool on) {
  state.autoScan = on;
  log_i("auto-scan %s", on ? "on" : "off");
}

void setLed(uint8_t r, uint8_t g, uint8_t b) {
  state.r = r, state.g = g, state.b = b;
  rgbLedWrite(PIN_RGB, r, g, b);
}

void applyCommand(const Command &c) {
  using T = Command::Type;
  switch (c.type) {
    case T::SetView: setView(c.value); break;
    case T::Scan: scanNow("web"); break;
    case T::SetAutoScan: setAuto(c.value != 0); break;
    case T::SetBacklight:
      state.backlight = uint8_t(c.value);
      display.setBacklight(state.backlight);
      log_i("backlight %u", state.backlight);
      break;
    case T::SetLed: setLed(c.r, c.g, c.b); break;
    case T::ShowMessage:
      state.message = c.text;
      setView(kMessageView);
      log_i("message from the web (%u characters)", unsigned(state.message.length()));
      break;
    case T::SaveWifi:
      connection.save(c.text, c.secret);
      setView(kStatusView);
      break;
    case T::ForgetWifi: connection.forget(); break;
    case T::Reboot:
      log_i("reboot requested");
      state.rebootAt = millis() + 800;  // let the HTTP answer go out first
      break;
  }
}

void startJoin(long number) {
  const auto &nets = scanner.networks();
  if (number < 1 || number > long(nets.size())) {
    log_w("join needs a number from the last scan table (1-%u)", unsigned(nets.size()));
    return;
  }
  const ScanResult &n = nets[number - 1];
  if (n.ssid.isEmpty()) {
    log_w("That network is hidden; its name is unknown, so it can't be joined from the list.");
    return;
  }
  if (n.auth == WIFI_AUTH_OPEN) {
    log_i("'%s' is open, joining without a password", n.ssid.c_str());
    connection.save(n.ssid, "");
    return;
  }
  state.pendingSsid = n.ssid;
  state.awaitingPassword = true;
  Serial.printf("Password for '%s' (the monitor shows what you type; it is stored on the chip only):\n", n.ssid.c_str());
}

// ---- Input -----------------------------------------------------------------------------

void handleButton(Button &b) {
  switch (b.poll()) {
    case Button::Event::Click:
      setView(state.view + 1);
      pushEvent(b.name(), "click");
      break;
    case Button::Event::DoubleClick:
      scanNow(b.name());
      pushEvent(b.name(), "double-click");
      break;
    case Button::Event::LongPress:
      setAuto(!state.autoScan);
      pushEvent(b.name(), "long-press");
      break;
    case Button::Event::None: break;
  }
}

void handleCommand(String raw) {
  // A password is taken exactly as typed: no lower-casing, no trimming of inner spaces.
  if (state.awaitingPassword) {
    state.awaitingPassword = false;
    connection.save(state.pendingSsid, raw);
    state.pendingSsid = "";
    setView(kStatusView);
    return;
  }
  String line = raw;
  line.trim();
  String lower = line;
  lower.toLowerCase();
  if (lower.isEmpty()) return;
  if (lower == "scan") return scanNow("serial");
  if (lower == "auto on" || lower == "auto off") return setAuto(lower == "auto on");
  if (lower == "forget") return connection.forget();
  if (lower == "reconnect") return connection.connect();
  if (lower == "status") return printStatus();
  if (lower == "ping" || lower.startsWith("ping ")) {
    IPAddress target = WiFi.gatewayIP();
    if (connection.state() != Connection::State::Connected) log_w("ping needs a network: join one first");
    else if (lower.length() > 5 && !target.fromString(line.substring(5))) log_w("not an IP address: %s", line.substring(5).c_str());
    else pinger.start(target);
    return;
  }
  if (lower == "relay" || lower.startsWith("relay ")) {
    if (!remote::builtIn()) log_w("this build has no remote link: flash wifi-lab-w2-remote");
    else if (lower == "relay") printRelay();
    else if (lower == "relay off") remote::setUrl("");
    else remote::setUrl(line.substring(6));  // as typed: host names can be mixed case
    return;
  }
  if (lower == "setup") return portal.start();
  if (lower == "token") {
    Serial.printf("Admin token: %s  (put it in esp32-labs/apps/dashboard/.env as ESP_TOKEN)\n", token.value().c_str());
    return;
  }
  if (lower == "token new") {
    token.regenerate();
    Serial.printf("New admin token: %s  (the old one stops working now)\n", token.value().c_str());
    return;
  }
  if (lower.startsWith("join ")) return startJoin(lower.substring(5).toInt());
  if (lower.startsWith("tz ")) return connection.setTimezone(line.substring(3));
  if (lower.startsWith("view ")) {
    const long v = lower.substring(5).toInt();
    if (v < 1 || v > kViews) {
      log_w("view needs 1-%d, got '%s'", kViews, lower.substring(5).c_str());
      return;
    }
    return setView(v - 1);
  }
  if (lower == "help" || lower == "?") return printHelp();
  log_w("unknown command '%s' (type help)", line.c_str());
}

void pollSerial() {
  static String buffer;
  while (Serial.available()) {
    const char c = Serial.read();
    if (c == '\n' || c == '\r') {
      if (!buffer.isEmpty() || state.awaitingPassword) handleCommand(buffer);
      buffer = "";
    } else if (buffer.length() < 96) {  // WPA passwords can be 63 characters
      buffer += c;
    }
  }
}

// Open the set-up network when there's nothing to join (or joining keeps failing),
// close it a while after we're connected.
void managePortal() {
  using State = Connection::State;
  static uint32_t failingSince = 0;
  const uint32_t now = millis();
  const State s = connection.state();
  if (s == State::NoCredentials) portal.start();
  if (s == State::Failed) {
    if (!failingSince) failingSince = now;
    if (now - failingSince > kPortalAfterFailMs) portal.start();
  } else if (s != State::Connecting) {
    failingSince = 0;
  }
  if (s == State::Connected && portal.activeFor() > kPortalCloseAfterJoinMs) portal.stop();
}

}  // namespace

void setup() {
  Serial.begin(115200);
  delay(1500);

  if (!display.begin()) {
    log_e("No memory for the frame buffer. Stopping.");
    return;
  }
  setLed(0, 0, 0);
  external.begin();
  boot.begin();
  commands.begin();
  token.begin();
  scanner.begin();
  portal.begin();
  connection.begin();
  web.begin();
  remote::begin(rules, token);
  log_i("%s: MAC %s. Radio: 2.4 GHz only.", kFirmware, WiFi.macAddress().c_str());
  Serial.printf("Admin token: %s  (for the dashboard's .env; serial command 'token' shows it again)\n", token.value().c_str());
  printHelp();
  // A scan can't start while the radio is busy joining; the loop scans once we're settled.
  if (connection.state() != Connection::State::Connecting) scanNow("start-up");
}

void loop() {
  FrameBuffer &fb = display.fb();
  if (fb.pixels() == nullptr) {
    delay(1000);
    return;
  }
  const uint32_t now = millis();
  if (state.rebootAt && now >= state.rebootAt) ESP.restart();

  pollSerial();
  handleButton(external);
  handleButton(boot);
  for (Command c; commands.pop(c);) applyCommand(c);
  connection.loop();
  portal.loop();
  managePortal();
  web.loop();
  if (connection.takeJustConnected()) setView(kStatusView);

  if (scanner.poll()) {
    if (scanner.failed()) log_w("scan failed, will retry");
    else log_i("scan %lu done: %u networks in %lu ms", static_cast<unsigned long>(scanner.scans()),
               unsigned(scanner.networks().size()), static_cast<unsigned long>(scanner.lastScanMs()));
    printResults();
    const String networks = networksJson();
    web.publishNetworks(networks);
    remote::publish("networks", networks);
  }
  // No automatic scans while joining (the radio must stay on the router's channel) or while the
  // set-up network is open (a scan would briefly cut off the phone that's setting us up).
  const bool joining = connection.state() == Connection::State::Connecting;
  // millis() here, not `now`: a scan that finished during poll() above has a finish time later
  // than `now`, and `now - finishedAt` would wrap around to a huge number and scan again at once.
  if (state.autoScan && !joining && !portal.active() && !scanner.scanning() &&
      millis() - scanner.finishedAt() >= autoScanInterval())
    scanNow("auto");

  static uint32_t lastPush = 0, lastTemp = 0;
  if (now - lastTemp >= 1000) {
    lastTemp = now;
    state.tempC = temperatureRead();
  }
  if (now - lastPush >= kStatusPushMs) {
    lastPush = now;
    const String status = statusJson();
    web.publishStatus(status);
    remote::publish("status", status);
  }

  if (state.view == 0 && now - state.pageFlippedAt >= kPageFlipMs) {
    state.page++;
    state.pageFlippedAt = now;
  }

  fb.fillScreen(pal::night);
  const auto &nets = scanner.networks();
  switch (state.view) {
    case 0: views::list(fb, nets, state.page); break;
    case 1: views::channels(fb, nets); break;
    case 2: views::radar(fb, nets, now / 1000.0f, scanner.scanning()); break;
    case kStatusView:
      if (portal.active() && connection.state() != Connection::State::Connected) views::setupScreen(fb, portal);
      else views::status(fb, connection, now / 1000.0f);
      break;
    default: views::message(fb, state.message, pal::amber); break;
  }
  views::header(fb, scanner, state.view, kViews, kViewNames[state.view], connection.state());
  // Remote link: a ring around the Wi-Fi dot, teal when the dashboard server is connected.
  if (remote::state() == remote::State::Online) fb.drawCircle(312, 20, 7, pal::teal);
  else if (remote::state() == remote::State::Connecting) fb.drawCircle(312, 20, 7, pal::amber);
  views::footer(fb, "click: view  double: scan  hold: auto", state.autoScan, scanner, autoScanInterval() / 1000);
  views::otaOverlay(fb, web.otaPercent());
  display.push();
}

// What each API request means, independent of how it arrived. The local web server (web_api.h)
// and the remote link (remote/relay.cpp) both call handle(), so a request is checked the same way
// whether it comes from your phone on the Wi-Fi or from the dashboard on the other side of a tunnel.
//
// Like every web-side code, it never changes anything itself: it validates, then queues a Command
// for loop() (see commands.h). Safe to call from any task.
#pragma once

#include <ArduinoJson.h>

#include "commands.h"
#include "connection.h"

struct ApiResult {
  int code;           // HTTP-style status: 200, 202, 400, 401, 404, 503
  const char *error;  // nullptr when it worked
  bool ok() const { return error == nullptr; }
};

class ApiRules {
 public:
  ApiRules(CommandQueue &queue, const Connection &connection, const char *const *viewNames, int viewCount)
      : queue_(queue), connection_(connection), viewNames_(viewNames), viewCount_(viewCount) {}

  // method + path as in the REST API (e.g. "PUT", "/api/led"); body is the parsed JSON object
  // (empty for requests without one). admin = the caller proved it has the token.
  ApiResult handle(const char *method, const char *path, JsonObjectConst body, bool admin) const {
    const String m = method, p = path;
    if (m == "POST" && p == "/api/scan") return push(Command{Command::Type::Scan}, 202);
    if (m == "PUT" && p == "/api/view") return view(body);
    if (m == "PUT" && p == "/api/settings") return settings(body);
    if (m == "PUT" && p == "/api/led") return led(body);
    if (m == "PUT" && p == "/api/message") return message(body);
    if (m == "PUT" && p == "/api/wifi") return saveWifi(body, admin);
    if (m == "DELETE" && p == "/api/wifi") return admin ? push(Command{Command::Type::ForgetWifi}) : kNeedsAdmin;
    if (m == "POST" && p == "/api/reboot") return admin ? push(Command{Command::Type::Reboot}, 202) : kNeedsAdmin;
    return {404, "no such endpoint, see /api"};
  }

  static constexpr ApiResult kNeedsAdmin{401, "admin action: send Authorization: Bearer <token> (serial command: token)"};

 private:
  ApiResult push(const Command &c, int code = 200) const {
    return queue_.push(c) ? ApiResult{code, nullptr} : ApiResult{503, "busy, try again"};
  }

  ApiResult view(JsonObjectConst body) const {
    const int v = viewIndex(body["view"]);
    if (v < 0) return {400, "view must be one of the names in /api/status screen.views"};
    Command c{Command::Type::SetView};
    c.value = v;
    return push(c);
  }

  ApiResult settings(JsonObjectConst body) const {
    const bool hasAuto = body["autoScan"].is<bool>(), hasLight = !body["backlight"].isNull();
    if (!hasAuto && !hasLight) return {400, "send autoScan (true/false) and/or backlight (0-255)"};
    const int level = body["backlight"] | -1;
    if (hasLight && (level < 0 || level > 255)) return {400, "backlight must be 0-255"};
    if (hasAuto) {
      Command c{Command::Type::SetAutoScan};
      c.value = body["autoScan"].as<bool>();
      if (const ApiResult r = push(c); !r.ok()) return r;
    }
    if (hasLight) {
      Command c{Command::Type::SetBacklight};
      c.value = level;
      return push(c);
    }
    return {200, nullptr};
  }

  ApiResult led(JsonObjectConst body) const {
    const int r = body["r"] | -1, g = body["g"] | -1, b = body["b"] | -1;
    if (r < 0 || r > 255 || g < 0 || g > 255 || b < 0 || b > 255) return {400, "r, g and b must be 0-255"};
    Command c{Command::Type::SetLed};
    c.r = r, c.g = g, c.b = b;
    return push(c);
  }

  ApiResult message(JsonObjectConst body) const {
    const char *text = body["text"] | "";
    if (strlen(text) > 96) return {400, "text is limited to 96 characters"};
    Command c{Command::Type::ShowMessage};
    strlcpy(c.text, text, sizeof(c.text));
    return push(c);
  }

  ApiResult saveWifi(JsonObjectConst body, bool admin) const {
    // During set-up nobody has the token yet (it's only on serial), so saving a network is open
    // until the board is joined. After that, changing networks is an admin action.
    if (connection_.state() == Connection::State::Connected && !admin) return kNeedsAdmin;
    const char *ssid = body["ssid"] | "";
    const char *pass = body["password"] | "";
    if (strlen(ssid) == 0 || strlen(ssid) > 32) return {400, "ssid must be 1-32 characters"};
    if (strlen(pass) > 63 || (strlen(pass) > 0 && strlen(pass) < 8)) return {400, "password must be empty (open network) or 8-63 characters"};
    Command c{Command::Type::SaveWifi};
    strlcpy(c.text, ssid, sizeof(c.text));
    strlcpy(c.secret, pass, sizeof(c.secret));
    return push(c, 202);
  }

  int viewIndex(JsonVariantConst v) const {
    if (v.is<int>()) {
      const int i = v.as<int>();
      return i >= 0 && i < viewCount_ ? i : -1;
    }
    const char *name = v | "";
    for (int i = 0; i < viewCount_; i++)
      if (strcmp(name, viewNames_[i]) == 0) return i;
    return -1;
  }

  CommandQueue &queue_;
  const Connection &connection_;
  const char *const *viewNames_;
  int viewCount_;
};

// How the web side talks to the rest of the program.
//
// Web requests are handled in the network task, while loop() owns the screen, the scanner
// and the connection. Changing those from two tasks at once would corrupt them. So a web
// request never changes anything itself: it drops a Command into a FreeRTOS queue, and
// loop() applies the queued commands at the start of every frame. One owner, no races.
#pragma once

#include <Arduino.h>
#include <freertos/FreeRTOS.h>
#include <freertos/queue.h>

struct Command {
  enum class Type : uint8_t { SetView, Scan, SetAutoScan, SetBacklight, SetLed, ShowMessage, SaveWifi, ForgetWifi, Reboot };
  Type type;
  int32_t value = 0;     // view index, on/off, backlight level
  uint8_t r = 0, g = 0, b = 0;
  char text[97] = {};    // message text, or SSID for SaveWifi
  char secret[65] = {};  // password for SaveWifi (never logged)
};

class CommandQueue {
 public:
  void begin() { queue_ = xQueueCreate(16, sizeof(Command)); }

  // From any task. Returns false when the queue is full (the request then answers 503).
  bool push(const Command &c) { return queue_ != nullptr && xQueueSend(queue_, &c, 0) == pdTRUE; }

  // From loop() only.
  bool pop(Command &c) { return queue_ != nullptr && xQueueReceive(queue_, &c, 0) == pdTRUE; }

 private:
  QueueHandle_t queue_ = nullptr;
};

// Remote control: the board dials OUT to your dashboard server and keeps a WebSocket open, so
// the dashboard can reach it from anywhere, through a tunnel (cloudflared, ngrok), without
// opening anything on your router.
//
// Two implementations, picked by the PlatformIO environment (like lesson 03b's controls):
//   remote/off.cpp     wifi-lab-w2          no remote link (everything returns "off")
//   remote/relay.cpp   wifi-lab-w2-remote   the WebSocket client, in its own FreeRTOS task
//
// The link speaks the same messages as the board's own /ws, plus requests and replies:
//   server -> board  {"type":"request","id":7,"method":"PUT","path":"/api/led","body":{...}}
//   board -> server  {"type":"reply","id":7,"status":200,"body":{"ok":true}}
//                    {"type":"status"|"networks"|"event","data":{...}}
// The board proves who it is with its admin token (Authorization header on the WebSocket
// upgrade); the server only accepts the board whose token is in its .env.
#pragma once

#include <Arduino.h>

#include "api_rules.h"
#include "api_token.h"

namespace remote {

enum class State : uint8_t { Off, NotConfigured, WaitingForWifi, Connecting, Online };

// false in plain W2: then the serial `relay` commands explain which build to flash.
bool builtIn();

// Reads the saved server address from NVS and starts the link task.
void begin(const ApiRules &rules, const ApiToken &token);

// Save a new server address ("" switches the link off). wss://host[/path] or ws://ip:port[/path];
// the path defaults to /device.
void setUrl(const String &url);
String url();

State state();

inline const char *stateName(State s) {
  switch (s) {
    case State::Off: return "off";
    case State::NotConfigured: return "not-configured";
    case State::WaitingForWifi: return "waiting-for-wifi";
    case State::Connecting: return "connecting";
    case State::Online: return "online";
  }
  return "?";
}

// From loop(): hand over the latest status/networks, or a button event. Thread-safe; the link
// task sends them when it can. Status is sent at most once per call, never queued up.
void publish(const char *type, const String &json);

}  // namespace remote

// The set-up network: when no Wi-Fi is saved (or joining keeps failing), the ESP32 also
// becomes an access point called "bench-setup". Join it from a phone, and every web address
// you open lands on the set-up page (a "captive portal"): a tiny DNS server answers every
// name with the ESP32's own address, 192.168.4.1.
//
// The access point's password is derived from the chip's MAC address and shown on the
// screen, so only someone who can see the board can use it.
#pragma once

#include <DNSServer.h>
#include <WiFi.h>

class SetupPortal {
 public:
  static constexpr const char *kSsid = "bench-setup";

  void begin() {
    uint8_t mac[6];
    WiFi.macAddress(mac);
    char pass[16];
    snprintf(pass, sizeof(pass), "bench-%02x%02x%02x", mac[3], mac[4], mac[5]);
    password_ = pass;
  }

  void start() {
    if (active_) return;
    WiFi.mode(WIFI_AP_STA);  // access point and station at the same time (one radio, shared channel)
    WiFi.softAP(kSsid, password_.c_str());
    dns_.start(53, "*", WiFi.softAPIP());
    active_ = true;
    startedAt_ = millis();
    log_i("Set-up network '%s' is up (password on the screen). Open http://%s", kSsid,
          WiFi.softAPIP().toString().c_str());
  }

  void stop() {
    if (!active_) return;
    dns_.stop();
    WiFi.softAPdisconnect(true);
    WiFi.mode(WIFI_STA);
    active_ = false;
    log_i("Set-up network closed");
  }

  void loop() {
    if (active_) dns_.processNextRequest();
  }

  bool active() const { return active_; }
  uint32_t activeFor() const { return active_ ? millis() - startedAt_ : 0; }
  const String &password() const { return password_; }
  String address() const { return WiFi.softAPIP().toString(); }

 private:
  DNSServer dns_;
  String password_;
  bool active_ = false;
  uint32_t startedAt_ = 0;
};

// The ESP32's web side: a small REST API, a WebSocket for live updates, the built-in phone page
// and firmware updates over HTTP. Runs on ESPAsyncWebServer, which answers requests in its own
// network task, so pages stay fast even while the screen is busy drawing.
//
// Endpoints (all JSON unless noted)
//   GET    /                 built-in phone page (HTML)
//   GET    /api              this list
//   GET    /api/status       device, Wi-Fi, screen and LED state
//   GET    /api/networks     last scan results
//   POST   /api/scan         start a scan                          -> 202
//   PUT    /api/view         {"view": "radar"}                     screen view
//   PUT    /api/settings     {"autoScan": true, "backlight": 180}  either or both
//   PUT    /api/led          {"r": 0, "g": 120, "b": 255}          on-board RGB LED
//   PUT    /api/message      {"text": "hello"}                     show text on the screen
//   PUT    /api/wifi         {"ssid": "...", "password": "..."}    open during set-up, admin after
//   DELETE /api/wifi         forget the saved network               admin
//   POST   /api/reboot       restart                                admin
//   POST   /api/ota          multipart firmware.bin                 admin
//   WS     /ws               pushes {"type": "status" | "networks" | "event" | "ota", "data": {...}}
//
// Admin = header "Authorization: Bearer <token>" (see api_token.h). Everything else is open on
// your local network: this is a bench toy, and nothing open can harm it.
#pragma once

#include <ArduinoJson.h>
#include <AsyncJson.h>
#include <ESPAsyncWebServer.h>
#include <Update.h>

#include <mutex>

#include "api_rules.h"
#include "api_token.h"
#include "commands.h"
#include "web_page.h"

class WebApi {
 public:
  WebApi(const ApiRules &rules, CommandQueue &queue, const ApiToken &token) : rules_(rules), queue_(queue), token_(token) {}

  void begin() {
    ws_.onEvent([this](AsyncWebSocket *, AsyncWebSocketClient *client, AwsEventType type, void *, uint8_t *, size_t) {
      if (type == WS_EVT_CONNECT) {
        // Send the latest picture straight away, so a new client doesn't wait a second.
        std::lock_guard<std::mutex> lock(mutex_);
        if (!status_.isEmpty()) client->text(wrap("status", status_));
        if (!networks_.isEmpty()) client->text(wrap("networks", networks_));
      }
    });
    server_.addHandler(&ws_);

    // A plain "/api" would also match every "/api/..." URL registered after it, so the two index
    // routes match exactly.
    server_.on(AsyncURIMatcher::exact("/"), HTTP_GET, [](AsyncWebServerRequest *req) {
      req->send(req->beginResponse(200, "text/html", reinterpret_cast<const uint8_t *>(kIndexHtml), strlen(kIndexHtml)));
    });
    server_.on(AsyncURIMatcher::exact("/api"), HTTP_GET, [](AsyncWebServerRequest *req) { req->send(200, "application/json", kApiIndex); });
    server_.on("/api/status", HTTP_GET, [this](AsyncWebServerRequest *req) { sendCached(req, status_); });
    server_.on("/api/networks", HTTP_GET, [this](AsyncWebServerRequest *req) { sendCached(req, networks_); });
    // The write endpoints: api_rules.h decides what each one means, here we only do HTTP.
    server_.on("/api/scan", HTTP_POST, [this](AsyncWebServerRequest *req) { route(req, "POST", JsonObjectConst()); });
    for (const char *path : {"/api/view", "/api/settings", "/api/led", "/api/message", "/api/wifi"}) {
      auto *h = new AsyncCallbackJsonWebHandler(path, [this](AsyncWebServerRequest *req, JsonVariant &body) {
        if (!body.is<JsonObject>()) return error(req, 400, "send a JSON object");
        route(req, "PUT", body.as<JsonObjectConst>());
      });
      h->setMethod(HTTP_PUT);
      h->setMaxContentLength(512);
      server_.addHandler(h);
    }
    server_.on("/api/wifi", HTTP_DELETE, [this](AsyncWebServerRequest *req) { route(req, "DELETE", JsonObjectConst()); });
    server_.on("/api/reboot", HTTP_POST, [this](AsyncWebServerRequest *req) { route(req, "POST", JsonObjectConst()); });
    server_.on(
        "/api/ota", HTTP_POST, [this](AsyncWebServerRequest *req) { finishOta(req); },
        [this](AsyncWebServerRequest *req, const String &, size_t index, uint8_t *data, size_t len, bool final) {
          receiveOta(req, index, data, len, final);
        });

    // In set-up mode every unknown address leads to the set-up page (that's the captive portal).
    server_.onNotFound([](AsyncWebServerRequest *req) {
      if (WiFi.getMode() & WIFI_AP && req->host() != WiFi.softAPIP().toString()) {
        req->redirect("http://" + WiFi.softAPIP().toString() + "/");
        return;
      }
      req->send(404, "application/json", "{\"error\":\"no such endpoint, see /api\"}");
    });
    server_.begin();
    log_i("Web server on port 80: phone page at /, API at /api, live updates at /ws");
  }

  // ---- Called from loop(): cache the latest JSON and push it to every WebSocket client ----

  void publishStatus(const String &json) { publish("status", json, status_); }
  void publishNetworks(const String &json) { publish("networks", json, networks_); }
  void publishEvent(const String &json) { ws_.textAll(wrap("event", json)); }

  void loop() {
    const uint32_t now = millis();
    if (now - lastCleanup_ > 2000) {
      lastCleanup_ = now;
      ws_.cleanupClients();
    }
    if (otaPercent_ >= 0 && otaPercent_ != lastOtaSent_) {
      lastOtaSent_ = otaPercent_;
      ws_.textAll(wrap("ota", "{\"percent\":" + String(otaPercent_) + "}"));
    }
  }

  int otaPercent() const { return otaPercent_; }
  size_t clients() const { return ws_.count(); }

 private:
  bool isAdmin(AsyncWebServerRequest *req) const {
    return req->hasHeader("Authorization") && token_.allows(req->header("Authorization"));
  }

  void route(AsyncWebServerRequest *req, const char *method, JsonObjectConst body) {
    const ApiResult r = rules_.handle(method, req->url().c_str(), body, isAdmin(req));
    if (!r.ok()) return error(req, r.code, r.error);
    req->send(r.code, "application/json", "{\"ok\":true}");
  }

  void enqueue(AsyncWebServerRequest *req, const Command &c, int code = 200) {
    if (!queue_.push(c)) return error(req, 503, "busy, try again");
    req->send(code, "application/json", "{\"ok\":true}");
  }

  static void error(AsyncWebServerRequest *req, int code, const char *message) {
    JsonDocument doc;
    doc["error"] = message;
    String out;
    serializeJson(doc, out);
    req->send(code, "application/json", out);
  }

  void sendCached(AsyncWebServerRequest *req, const String &cached) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (cached.isEmpty()) req->send(503, "application/json", "{\"error\":\"starting up\"}");
    else req->send(200, "application/json", cached);
  }

  void publish(const char *type, const String &json, String &cache) {
    {
      std::lock_guard<std::mutex> lock(mutex_);
      cache = json;
    }
    if (ws_.count() > 0) ws_.textAll(wrap(type, json));
  }

  static String wrap(const char *type, const String &data) {
    return String("{\"type\":\"") + type + "\",\"data\":" + data + "}";
  }

  // ---- Firmware update over HTTP ----------------------------------------------------------
  // The upload arrives in chunks. Update writes them to the *other* app partition, checks the
  // image, and marks it to boot next time. The running firmware is untouched until the reboot,
  // so a failed upload changes nothing.

  void receiveOta(AsyncWebServerRequest *req, size_t index, uint8_t *data, size_t len, bool final) {
    if (index == 0) {
      otaAuthorized_ = req->hasHeader("Authorization") && token_.allows(req->header("Authorization"));
      otaError_ = "";
      if (!otaAuthorized_) return;
      otaTotal_ = req->contentLength();
      if (!Update.begin(UPDATE_SIZE_UNKNOWN, U_FLASH)) {
        otaError_ = Update.errorString();
        return;
      }
      otaPercent_ = 0;
      log_i("Firmware update started (%u bytes incoming)", unsigned(otaTotal_));
    }
    if (!otaAuthorized_ || !otaError_.isEmpty()) return;
    if (Update.write(data, len) != len) {
      otaError_ = Update.errorString();
      Update.abort();
      otaPercent_ = -1;
      return;
    }
    if (otaTotal_ > 0) otaPercent_ = int((index + len) * 100 / otaTotal_);
    if (final) {
      if (Update.end(true)) {
        otaPercent_ = 100;
      } else {
        otaError_ = Update.errorString();
        otaPercent_ = -1;
      }
    }
  }

  void finishOta(AsyncWebServerRequest *req) {
    if (!otaAuthorized_) return error(req, 401, "admin action: send Authorization: Bearer <token>");
    if (!otaError_.isEmpty()) {
      log_e("Firmware update failed: %s", otaError_.c_str());
      return error(req, 500, otaError_.c_str());
    }
    log_i("Firmware update written and verified. Rebooting into it.");
    enqueue(req, Command{Command::Type::Reboot}, 200);
  }

  static constexpr const char *kApiIndex =
      R"JSON({"endpoints":["GET /api/status","GET /api/networks","POST /api/scan","PUT /api/view","PUT /api/settings","PUT /api/led","PUT /api/message","PUT /api/wifi","DELETE /api/wifi (admin)","POST /api/reboot (admin)","POST /api/ota (admin)","WS /ws"]})JSON";

  const ApiRules &rules_;
  CommandQueue &queue_;  // only for the reboot after a firmware update
  const ApiToken &token_;
  AsyncWebServer server_{80};
  AsyncWebSocket ws_{"/ws"};
  std::mutex mutex_;
  String status_, networks_;
  uint32_t lastCleanup_ = 0;
  volatile int otaPercent_ = -1;
  int lastOtaSent_ = -1;
  bool otaAuthorized_ = false;
  size_t otaTotal_ = 0;
  String otaError_;
};

// W2's own screens, on top of the shared ones in kit/lib/wifi-kit/src/views.h.
//   Set-up    while the set-up network is open: what a phone needs to join it
//   Message   text sent from the phone page or the dashboard (view 5)
//   Overlay   firmware update progress
#pragma once

#include "setup_portal.h"
#include "views.h"

namespace views {

// ---- Set-up network: replaces the status view while it's open and we're not joined --------

inline void setupScreen(FrameBuffer &fb, const SetupPortal &portal) {
  fb.setFont(&FreeSans9pt7b);
  fb.setTextColor(pal::ink);
  fb.setCursor(8, 52);
  fb.print("Set up from your phone");
  fb.setFont(nullptr);
  const char *labels[] = {"Wi-Fi", "Password", "Then open"};
  const String values[] = {SetupPortal::kSsid, portal.password(), "http://" + portal.address()};
  for (int i = 0; i < 3; i++) {
    fb.setTextColor(pal::muted);
    fb.setCursor(8, 70 + i * 22);
    fb.print(labels[i]);
    fb.setFont(&FreeSans9pt7b);
    fb.setTextColor(i == 1 ? pal::amber : pal::teal);
    fb.setCursor(80, 80 + i * 22);
    fb.print(values[i]);
    fb.setFont(nullptr);
  }
  fb.setTextColor(pal::muted);
  fb.setCursor(8, 140);
  fb.print("or in the serial monitor: join <#>");
}

// ---- View 5: a message sent from the web ---------------------------------------------------

inline void message(FrameBuffer &fb, const String &text, uint16_t accent) {
  if (text.isEmpty()) {
    fb.setFont(&FreeSans9pt7b);
    fb.setTextColor(pal::muted);
    fb.setCursor(8, 70);
    fb.print("No message yet");
    fb.setFont(nullptr);
    fb.setCursor(8, 90);
    fb.print("Send one from http://bench.local or the dashboard");
    return;
  }
  // Word-wrap into up to 3 lines of the big font; fall back to the small font for long text.
  const GFXfont *font = text.length() <= 30 ? &FreeSansBold18pt7b : &FreeSans9pt7b;
  const int lineH = font == &FreeSansBold18pt7b ? 36 : 20, maxW = kW - 24;
  fb.setFont(font);
  fb.setTextColor(accent);
  String line, word;
  int y = font == &FreeSansBold18pt7b ? 72 : 56;
  auto flush = [&]() {
    fb.setCursor(12, y);
    fb.print(line);
    y += lineH;
    line = "";
  };
  for (size_t i = 0; i <= text.length(); i++) {
    const char ch = i < text.length() ? text[i] : ' ';
    if (ch != ' ') {
      word += ch;
      continue;
    }
    const String candidate = line.isEmpty() ? word : line + " " + word;
    int16_t x1, y1;
    uint16_t w, h;
    fb.getTextBounds(candidate, 0, 0, &x1, &y1, &w, &h);
    if (w > maxW && !line.isEmpty()) flush();
    line = line.isEmpty() ? word : line + " " + word;
    word = "";
    if (y > kH - 14) break;
  }
  if (!line.isEmpty() && y <= kH - 14) flush();
}

// ---- Overlay: firmware update progress ------------------------------------------------------

inline void otaOverlay(FrameBuffer &fb, int percent) {
  if (percent < 0) return;
  fb.fillRoundRect(30, 56, kW - 60, 60, 10, pal::night);
  fb.drawRoundRect(30, 56, kW - 60, 60, 10, pal::amber);
  fb.setFont(&FreeSans9pt7b);
  fb.setTextColor(pal::ink);
  fb.setCursor(44, 80);
  fb.printf("Updating firmware  %d%%", percent);
  fb.fillRoundRect(44, 92, kW - 88, 10, 4, pal::dim);
  fb.fillRoundRect(44, 92, (kW - 88) * percent / 100, 10, 4, pal::amber);
}

}  // namespace views

